/** Gentle, probabilistic: «похоже на…», never a diagnosis. */
export function detectTrap(text) {
  const value = ` ${String(text || '').toLowerCase().replace(/ё/g, 'е')} `;
  if (value.trim().length < 6) return null;
  const order = ['label', 'catastrophe', 'mindreading', 'should', 'personal', 'discount', 'magnify', 'emotional', 'blackwhite', 'filter', 'tunnel', 'overgeneral'];
  for (const id of order) {
    const trap = TRAPS.find((item) => item.id === id);
    if (trap.markers.some((marker) => value.includes(marker.replace(/ё/g, 'е')))) return trap;
  }
  return null;
}

